#!/bin/sh
# data/known_codes.json -> app/Sources/EnetCore/KnownCodes.swift (the app carries it compiled in)
set -e
cd "$(dirname "$0")/.."
python3 -I - <<'PY'
import json
d = json.load(open('data/known_codes.json'))
for e in d['entries']:
    for k in ('address', 'code', 'severity', 'pl', 'en'):
        assert k in e, (e.get('code'), k)
    assert e['severity'] in ('workshop', 'watch', 'info'), e['code']
s = json.dumps({'entries': d['entries']}, ensure_ascii=False, separators=(',', ':'))
assert '"""#' not in s
open('app/Sources/EnetCore/KnownCodes.swift', 'w').write(
    '// Generated by tools/embed-codes.sh from data/known_codes.json - edit that file, not this one.\n'
    'enum KnownCodes {\n    static let json = #"""\n' + s + '\n"""#\n}\n')
print(len(d['entries']), 'codes')
PY
